"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68965"],{5599(e){e.exports=JSON.parse('{"id":"F017","slug":"pv-growing-annuity","name":"Present Value of a Growing Annuity","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","level":"Intermediate","aliases":["growing annuity","payments that grow each year","salary stream value"],"formula":{"latex":"PV = \\\\frac{C_{1}}{r-g}\\\\left[1-\\\\left(\\\\frac{1+g}{1+r}\\\\right)^{n}\\\\right]","also":[],"text":"PV = C1 / (r - g) x (1 - ((1 + g) / (1 + r))^n)"},"symbols":[{"symbol":"PV","meaning":"Present value of the growing payments","unit":"money"},{"symbol":"C1","meaning":"The first payment, received at the end of period 1","unit":"money"},{"symbol":"r","meaning":"Discount rate per period, as a decimal","unit":"per period"},{"symbol":"g","meaning":"Growth rate of the payment each period, as a decimal","unit":"per period"},{"symbol":"n","meaning":"Number of payments","unit":"periods"}],"when_to_use":"Use it for a limited number of payments that grow at a steady rate, such as a salary that rises each year until retirement. With no growth it becomes the ordinary annuity formula.","worked_example":{"problem":"A plan pays 1,000 at the end of next year, and each payment after that grows by 3%. It makes 10 payments. With a discount rate of 8%, what is it worth today?","inputs":{"C1":1000,"r":8,"g":3,"n":10},"steps":[{"label":"Growth ratio = (1 + g) / (1 + r)","working":"(1+0.03) / (1+0.08)","value":"0.9537"},{"label":"Bracket = 1 - ratio^n","working":"1-0.953704^10","value":"0.3775"},{"label":"PV = C1 / (r - g) x bracket","working":"1000 / (0.08-0.03) x 0.377507","value":"7,550.13"}],"answer":"The 10 growing payments are worth 7,550.13 today."},"calculator":{"available":true,"inputs":[{"id":"C1","label":"First payment","unit":"money","type":"number","default":1000,"hint":""},{"id":"r","label":"Discount rate per period","unit":"%","type":"number","default":8,"hint":""},{"id":"g","label":"Growth rate per period","unit":"%","type":"number","default":3,"hint":""},{"id":"n","label":"Number of payments","unit":"periods","type":"number","default":10,"hint":"","min":1}],"checks":[{"expr":"r!=g","message":"The discount rate and growth rate cannot be equal. In that case the answer is simply C1 x n / (1 + r)."}],"steps":[{"id":"ratio","label":"Growth ratio = (1 + g) / (1 + r)","expr":"(1+g)/(1+r)","format":"num4"},{"id":"inner","label":"Bracket = 1 - ratio^n","expr":"1-ratio^n","format":"num4"},{"id":"pv","label":"PV = C1 / (r - g) x bracket","expr":"C1/(r-g)*inner","format":"money"}],"results":["pv"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pv":7550.133691149122}},"finder":{"finds":"Value today of payments that grow for a fixed number of periods","needs":"First payment, rate, growth, number of payments"},"related":[{"slug":"pv-ordinary-annuity","name":"Present Value of an Ordinary Annuity"},{"slug":"growing-perpetuity","name":"Growing Perpetuity"}],"related_ids":["F019","F021"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mi>V</mi><mo>=</mo><mfrac><msub><mi>C</mi><mn>1</mn></msub><mrow><mi>r</mi><mo>\u2212</mo><mi>g</mi></mrow></mfrac><mrow><mo fence=\\"true\\">[</mo><mn>1</mn><mo>\u2212</mo><msup><mrow><mo fence=\\"true\\">(</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>g</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo fence=\\"true\\">)</mo></mrow><mi>n</mi></msup><mo fence=\\"true\\">]</mo></mrow></mrow><annotation encoding=\\"application/x-tex\\">PV = \\\\frac{C_{1}}{r-g}\\\\left[1-\\\\left(\\\\frac{1+g}{1+r}\\\\right)^{n}\\\\right]</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"preferred-stock-value","name":"Preferred Stock Value"},"next":{"slug":"pv-lump-sum","name":"Present Value of a Lump Sum"},"lesson":null,"total":522}')}}]);